diff --git a/src/slugify.js b/src/slugify.js
index 775eb1e..3310085 100644
--- a/src/slugify.js
+++ b/src/slugify.js
@@ -1,10 +1,36 @@
+// Letters whose ASCII spelling is not supplied by canonical decomposition.
+const latinSpellings = new Map([
+	["æ", "ae"], ["œ", "oe"], ["ß", "ss"], ["ø", "o"],
+	["ł", "l"], ["đ", "d"], ["ð", "d"], ["þ", "th"],
+	["ħ", "h"], ["ı", "i"], ["ŋ", "n"], ["ŧ", "t"],
+	["ſ", "s"], ["ƒ", "f"], ["ĸ", "k"], ["ŀ", "l"],
+	["ĳ", "ij"], ["ǆ", "dz"], ["ǉ", "lj"], ["ǌ", "nj"],
+	["ǳ", "dz"], ["ƀ", "b"], ["ƃ", "b"], ["ƈ", "c"],
+	["ƌ", "d"], ["ɖ", "d"], ["ɗ", "d"], ["ɠ", "g"],
+	["ɦ", "h"], ["ɨ", "i"], ["ƙ", "k"], ["ƚ", "l"],
+	["ɫ", "l"], ["ƞ", "n"], ["ɵ", "o"], ["ƥ", "p"],
+	["ʠ", "q"], ["ʈ", "t"], ["ƭ", "t"], ["ʉ", "u"],
+	["ʋ", "v"], ["ƴ", "y"], ["ƶ", "z"], ["ȝ", "g"],
+	["ȡ", "d"], ["ȴ", "l"], ["ȵ", "n"], ["ȶ", "t"],
+	["ȷ", "j"], ["ȼ", "c"], ["ȿ", "s"], ["ɀ", "z"],
+	["ɇ", "e"], ["ɉ", "j"], ["ɍ", "r"], ["ɏ", "y"],
+	["ꜳ", "aa"], ["ꜵ", "ao"], ["ꜷ", "au"], ["ꜹ", "av"],
+	["ꜻ", "av"], ["ꜽ", "ay"], ["ꝏ", "oo"], ["ꝡ", "vy"],
+	["ﬀ", "ff"], ["ﬁ", "fi"], ["ﬂ", "fl"], ["ﬃ", "ffi"],
+	["ﬄ", "ffl"], ["ﬅ", "st"], ["ﬆ", "st"],
+]);
+
 /**
- * Turns a title into a URL slug: lower case, runs of anything that is not a letter or a digit become one hyphen, and
- * no hyphen at either end. Letters of every script are kept.
+ * Turns a title into a URL slug: lower case, ASCII spellings for accented Latin
+ * letters, runs of non-letters and non-digits become one hyphen, and no hyphen
+ * at either end.
  */
 export function slugify(title) {
 	return title
 		.toLowerCase()
+		.normalize("NFD")
+		.replace(/\p{M}+/gu, "")
+		.replace(/\p{Script=Latin}/gu, letter => latinSpellings.get(letter) ?? letter)
 		.replace(/[^\p{L}\p{N}]+/gu, "-")
 		.replace(/^-+|-+$/g, "");
 }
diff --git a/test/slugify.test.js b/test/slugify.test.js
index 52bb499..50b0b96 100644
--- a/test/slugify.test.js
+++ b/test/slugify.test.js
@@ -18,3 +18,16 @@ test("turns Latin letters with diacritics into ASCII", () => {
 	assert.equal(slugify("Crème Brûlée"), "creme-brulee");
 	assert.equal(slugify("Łódź"), "lodz");
 });
+
+test("handles Latin strokes and ligatures", () => {
+	assert.equal(slugify("Æsir smørrebrød Straße"), "aesir-smorrebrod-strasse");
+	assert.equal(slugify("Œuvre Þing Đorđe"), "oeuvre-thing-dorde");
+});
+
+test("handles combining accents in Latin titles", () => {
+	assert.equal(slugify("Cre\u0300me Bru\u0302le\u0301e"), "creme-brulee");
+});
+
+test("keeps Greek and Japanese letters", () => {
+	assert.equal(slugify("ΑΒΓ 東京"), "αβγ-東京");
+});
